<script setup lang="ts">
import { onMounted, onUnmounted, ref } from "vue";
import { useAuth } from "@papilio/auth";
import { item, request, query, type Page, type SmsOriginCapabilities, type SmsParserProfile, type SmsParserRevision, type SmsParserDefinition, type SmsParserPreview, type SmsAmountUnit } from "@papilio/api";
import { faDate, faNumber, toman } from "@papilio/ui";
import Modal from "@papilio/ui/Modal.vue";
import { createSmsParserClient } from "../../workers/smsParserClient";
import SmsParserDefinitionEditor from "./SmsParserDefinitionEditor.vue";
const props=defineProps<{capabilities:SmsOriginCapabilities}>();
const mayMutate=()=>props.capabilities.enabled&&props.capabilities.capacity!==null;
const parserClient=createSmsParserClient();
const auth=useAuth(),base="/v1/admin/payments/sms-origins/parser-profiles";
const rows=ref<SmsParserProfile[]>([]),page=ref(1),pages=ref(1),q=ref(""),loading=ref(false),error=ref(""),busy=ref(false);
const open=ref(false),selected=ref<SmsParserProfile|null>(null),title=ref(""),active=ref(false),definition=ref(""),expected=ref<number|null>(null),draftError=ref(""),draftReady=ref(false),conflict=ref<SmsParserProfile|null>(null);
const revisions=ref<SmsParserRevision[]>([]),revisionPage=ref(1),revisionPages=ref(1),revisionLoading=ref(false),chosenText=ref(""),chosen=ref<SmsParserRevision|null>(null);
const deposit=ref(""),balance=ref(""),reference=ref(""),depositIndex=ref(0),balanceIndex=ref<number|null>(null),unit=ref<SmsAmountUnit>("rial"),preview=ref<SmsParserPreview|null>(null);
let alive=true,listSequence=0,editorSequence=0,revisionSequence=0;
function message(cause:unknown):string{return cause instanceof Error?cause.message:"The operation failed. Your draft is retained.";}
async function load():Promise<void>{const sequence=++listSequence;loading.value=true;error.value="";try{const result=await request<Page<SmsParserProfile>>(`${base}?${query({page:page.value,q:q.value})}`);if(!alive||sequence!==listSequence)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;}catch(cause){if(alive&&sequence===listSequence)error.value=message(cause);}finally{if(alive&&sequence===listSequence)loading.value=false;}}
function emptyDefinition():SmsParserDefinition{return {mode:props.capabilities.parser_modes[0]!,credit_markers:[],debit_markers:[],clause_separators:[],deposit_relations:[],balance_relations:[],reference_labels:[],rial_labels:[],toman_labels:[],grouping_separators:[],case_sensitive:false};}
function create():void{if(busy.value||!mayMutate())return;if(selected.value||!draftReady.value){selected.value=null;title.value="";active.value=false;definition.value=JSON.stringify(emptyDefinition(),null,2);expected.value=null;chosen.value=null;revisions.value=[];preview.value=null;}draftError.value="";conflict.value=null;draftReady.value=true;open.value=true;}
async function edit(row:SmsParserProfile):Promise<void>{if(busy.value)return;if(selected.value?.id===row.id&&draftReady.value){open.value=true;return;}const sequence=++editorSequence;selected.value=row;open.value=true;draftReady.value=false;draftError.value="";preview.value=null;chosen.value=null;conflict.value=null;revisions.value=[];busy.value=true;try{const current=await item<SmsParserProfile>(`${base}/${row.id}`);const revision=await item<SmsParserRevision>(`${base}/${row.id}/revisions/${current.revision}`);if(!alive||sequence!==editorSequence)return;selected.value=current;expected.value=current.revision;title.value=current.title;active.value=current.is_active;const formatted=await parserClient.compute({value:revision.definition,capabilities:props.capabilities});if(!alive||sequence!==editorSequence)return;if(!formatted.text)throw new Error(formatted.error??"The saved definition could not be displayed.");definition.value=formatted.text;chosenText.value=formatted.text;chosen.value=revision;draftReady.value=true;revisionPage.value=1;await loadRevisions();}catch(cause){if(alive&&sequence===editorSequence)draftError.value=message(cause);}finally{if(alive&&sequence===editorSequence)busy.value=false;}}
async function loadRevisions():Promise<void>{const id=selected.value?.id;if(!id)return;const sequence=++revisionSequence;revisionLoading.value=true;try{const result=await request<Page<SmsParserRevision>>(`${base}/${id}/revisions?${query({page:revisionPage.value})}`);if(!alive||sequence!==revisionSequence||selected.value?.id!==id)return;revisions.value=result.data;revisionPages.value=result.meta.pager?.total_pages??1;}catch(cause){if(alive&&sequence===revisionSequence)draftError.value=message(cause);}finally{if(alive&&sequence===revisionSequence)revisionLoading.value=false;}}
async function parsedDefinition():Promise<SmsParserDefinition>{const reply=await parserClient.compute({text:definition.value,capabilities:props.capabilities});if(!reply.valid||!reply.value)throw new Error(reply.error??"Enter a valid parser definition.");return reply.value;}
async function save():Promise<void>{if(!mayMutate()||busy.value||!draftReady.value||!auth.can("payments",selected.value?"update":"create"))return;busy.value=true;draftError.value="";try{const data={title:title.value.trim(),is_active:active.value,definition:await parsedDefinition(),...(selected.value?{expected_revision:expected.value}:{})};const result=await item<SmsParserProfile>(selected.value?`${base}/${selected.value.id}`:base,selected.value?"PUT":"POST",data);if(!alive)return;selected.value=result;expected.value=result.revision;open.value=false;draftReady.value=false;await load();}catch(cause){if(alive)draftError.value=message(cause);}finally{if(alive)busy.value=false;}}
async function refreshCurrent():Promise<void>{if(!selected.value||busy.value)return;busy.value=true;try{conflict.value=await item<SmsParserProfile>(`${base}/${selected.value.id}`);}catch(cause){draftError.value=message(cause);}finally{busy.value=false;}}
async function selectRevision(row:SmsParserRevision):Promise<void>{if(busy.value)return;chosen.value=row;chosenText.value="";preview.value=null;depositIndex.value=0;balanceIndex.value=null;try{const formatted=await parserClient.compute({value:row.definition,capabilities:props.capabilities});if(alive&&chosen.value?.id===row.id)chosenText.value=formatted.text??formatted.error??"Definition unavailable.";}catch(cause){if(alive)draftError.value=message(cause);}}
async function sample():Promise<void>{const row=chosen.value,id=selected.value?.id;if(!row||!id||busy.value||!mayMutate())return;busy.value=true;draftError.value="";preview.value=null;try{const amount=Number(deposit.value),remaining=balanceIndex.value===null?null:Number(balance.value);if(!deposit.value||!Number.isSafeInteger(amount)||amount<=0||remaining!==null&&(!balance.value||!Number.isSafeInteger(remaining)||remaining<0))throw new Error("Enter whole rial amounts for the generated sample.");const result=await item<SmsParserPreview>(`${base}/${id}/revisions/${row.revision}/sample`,"POST",{deposit_relation_index:depositIndex.value,deposit_rial:amount,balance_relation_index:balanceIndex.value,balance_rial:remaining,unit:unit.value,bank_reference:reference.value.trim()||null});if(alive&&selected.value?.id===id&&chosen.value?.id===row.id)preview.value=result;}catch(cause){if(alive)draftError.value=message(cause);}finally{if(alive)busy.value=false;}}
onMounted(load);onUnmounted(()=>{alive=false;++listSequence;++editorSequence;++revisionSequence;parserClient.close();});
</script>
<template>
<section class="record-section"><div class="page-head"><div><h3>Bank SMS parser profiles</h3><p class="subtitle">Versioned literal rules for deposit, balance and bank reference recognition.</p></div><button v-if="capabilities.enabled&&auth.can('payments','create')" class="btn" :disabled="busy" @click="create">Create parser profile</button></div><form class="toolbar" @submit.prevent="page=1;load()"><label class="field"><span>Find parser profile</span><input v-model="q"/></label><button class="btn secondary" :disabled="loading">Search</button></form><p v-if="error" class="message error" role="alert">{{error}}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Profile</th><th>Version</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.title}}</td><td>{{faNumber(row.revision)}}</td><td>{{row.is_active?'Enabled':'Disabled'}}</td><td><button class="btn small secondary" :disabled="busy" @click="edit(row)">Open profile</button></td></tr></tbody></table></div><p v-if="loading" role="status">Loading profiles…</p><p v-else-if="!rows.length&&!error">No parser profiles found.</p><div class="pager"><button :disabled="page<=1||loading" @click="page--;load()">‹</button><span>Page {{faNumber(page)}} / {{faNumber(pages)}}</span><button :disabled="page>=pages||loading" @click="page++;load()">›</button></div></section>
<Modal v-model="open" :title="selected?'Parser profile: '+selected.title:'Create parser profile'" :busy="busy" wide><p v-if="draftError" class="message error" role="alert">{{draftError}}</p><p v-if="!draftReady">Loading saved parser definition…</p><form v-else class="form-grid" @submit.prevent="save"><fieldset class="form-grid" :disabled="!capabilities.enabled||busy||!auth.can('payments',selected?'update':'create')"><label class="field"><span>Profile title</span><input v-model="title" required maxlength="100"/></label><label class="check-row"><input v-model="active" type="checkbox"/>Profile enabled</label><SmsParserDefinitionEditor v-model="definition" :capabilities="capabilities" :disabled="!capabilities.enabled||busy||!auth.can('payments',selected?'update':'create')"/><details><summary>Advanced definition JSON</summary><label class="field"><span>Literal parser definition JSON</span><textarea v-model="definition" class="json-editor" spellcheck="false" required/><small>Literal markers and explicit amount relations only. Deposit and balance rules are separate; executable regular expressions are unsupported.</small></label></details><button class="btn">{{selected?'Save new immutable revision':'Create profile'}}</button></fieldset></form><div v-if="selected&&draftReady" class="inline-actions"><button class="btn secondary" :disabled="busy" @click="refreshCurrent">Check current revision</button><p v-if="conflict">Current saved revision {{faNumber(conflict.revision)}}; draft targets {{faNumber(expected??0)}}.</p><button v-if="conflict&&conflict.revision!==expected&&auth.can('payments','update')" class="btn secondary" :disabled="busy" @click="expected=conflict.revision">Use reviewed current revision for this retained draft</button></div>
<section v-if="selected&&draftReady"><h3>Immutable revision history</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Revision</th><th>Created</th><th>Actor</th><th></th></tr></thead><tbody><tr v-for="row in revisions" :key="row.id"><td>{{faNumber(row.revision)}}</td><td>{{faDate(row.created_at)}}</td><td>{{row.created_by_staff_id===null?'System':'Staff #'+row.created_by_staff_id}}</td><td><button class="btn small secondary" :disabled="busy" @click="selectRevision(row)">{{chosen?.id===row.id?'Selected':'Inspect / preview'}}</button></td></tr></tbody></table></div><p v-if="revisionLoading">Loading revisions…</p><div class="pager"><button :disabled="revisionPage<=1||revisionLoading||busy" @click="revisionPage--;loadRevisions()">‹</button><span>{{faNumber(revisionPage)}} / {{faNumber(revisionPages)}}</span><button :disabled="revisionPage>=revisionPages||revisionLoading||busy" @click="revisionPage++;loadRevisions()">›</button></div><template v-if="chosen"><h3>Selected revision {{faNumber(chosen.revision)}}</h3><code class="digest">{{chosen.definition_sha256}}</code><details><summary>Saved immutable definition</summary><pre>{{chosenText||'Formatting saved definition…'}}</pre></details><p class="hint-box">Generate a synthetic sample for this saved revision. A preview never approves a payment and does not test unsaved changes.</p><form class="form-grid" @submit.prevent="sample"><label class="field"><span>Deposit rule</span><select v-model.number="depositIndex" :disabled="busy"><option v-for="(rule,index) in chosen.definition.deposit_relations" :key="index" :value="index">{{rule.marker}} · {{rule.relation}}</option></select></label><label class="field"><span>Generated deposit (rial)</span><input v-model="deposit" inputmode="numeric" required :disabled="busy"/></label><label class="field"><span>Balance rule</span><select v-model="balanceIndex" :disabled="busy"><option :value="null">No balance in sample</option><option v-for="(rule,index) in chosen.definition.balance_relations" :key="index" :value="index">{{rule.marker}} · {{rule.relation}}</option></select></label><label v-if="balanceIndex!==null" class="field"><span>Generated balance (rial)</span><input v-model="balance" inputmode="numeric" required :disabled="busy"/></label><label class="field"><span>Currency token</span><select v-model="unit" :disabled="busy"><option v-for="value in capabilities.units" :key="value" :value="value">{{value}}</option></select></label><label class="field"><span>Synthetic bank reference (optional)</span><input v-model="reference" minlength="4" maxlength="128" :disabled="busy"/></label><button class="btn secondary" :disabled="!capabilities.enabled||busy||!chosen.definition.deposit_relations.length">Generate parser preview</button></form><section v-if="preview" aria-label="Generated parser preview"><pre>{{preview.generated_message}}</pre><p>Direction: {{preview.direction}} · Deposit: {{preview.deposit_rial===null?'Not identified':toman(preview.deposit_rial)}} · Balance: {{preview.balance_rial===null?'Not identified':toman(preview.balance_rial)}}</p><p>Bank reference: {{preview.bank_reference??'Not identified'}}</p><p v-if="preview.reason_code">Parser reason: <code>{{preview.reason_code}}</code></p><span class="badge warning">Parser preview only · Not eligible for settlement</span></section></template></section>
</Modal>
</template>
<style scoped>.record-section{margin-top:24px;padding-top:20px;border-top:1px solid var(--line)}.json-editor{min-height:260px;font-family:monospace;direction:ltr}.digest,pre{overflow-wrap:anywhere;white-space:pre-wrap}fieldset{border:0;padding:0;margin:0;min-width:0}</style>
